// Normalize all job data from different sources into a unified schema
const allJobs = [];
const now = new Date().toISOString();

for (const item of $input.all()) {
  const raw = item.json;

  // Remote OK
  if (raw.id && raw.slug && raw.company) {
    allJobs.push({
      job_id: `remoteok-${raw.id}`,
      source: 'Remote OK',
      job_title: raw.position || '',
      company: raw.company || '',
      job_url: raw.url || `https://remoteok.com/remote-jobs/${raw.slug}`,
      location_text: raw.location || 'Worldwide',
      salary: raw.salary || '',
      description: raw.description || raw.tags?.join(' ') || '',
      posted_date: raw.date || '',
      tags: Array.isArray(raw.tags) ? raw.tags.join(', ') : '',
      date_found: now
    });
    continue;
  }

  // Remotive
  if (raw.job_type !== undefined && raw.candidate_required_location !== undefined) {
    allJobs.push({
      job_id: `remotive-${raw.id}`,
      source: 'Remotive',
      job_title: raw.title || '',
      company: raw.company_name || '',
      job_url: raw.url || '',
      location_text: raw.candidate_required_location || 'Worldwide',
      salary: raw.salary || '',
      description: raw.description || '',
      posted_date: raw.publication_date || '',
      tags: Array.isArray(raw.tags) ? raw.tags.join(', ') : raw.tags || '',
      date_found: now
    });
    continue;
  }

  // RSS feeds (WWR, Himalayas, Dynamite)
  if (raw.link && raw.title) {
    const sourceMap = {
      'weworkremotely': 'We Work Remotely',
      'himalayas': 'Himalayas',
      'dynamitejobs': 'Dynamite Jobs'
    };
    let src = 'RSS Source';
    for (const [key, val] of Object.entries(sourceMap)) {
      if ((raw.link || '').includes(key)) { src = val; break; }
    }
    const desc = raw.contentSnippet || raw.content || raw.summary || '';
    const companyMatch = desc.match(/company[:\s]+([^\n]+)/i);
    allJobs.push({
      job_id: `rss-${Buffer.from(raw.link || raw.title).toString('base64').slice(0,20)}`,
      source: src,
      job_title: raw.title || '',
      company: companyMatch ? companyMatch[1].trim() : (raw.author || 'Unknown'),
      job_url: raw.link || '',
      location_text: raw.location || 'See description',
      salary: '',
      description: desc,
      posted_date: raw.pubDate || raw.isoDate || '',
      tags: raw.categories?.join(', ') || '',
      date_found: now
    });
    continue;
  }

  // Wellfound / YC / Otta - basic passthrough for manual mapping
  if (raw.title || raw.name) {
    allJobs.push({
      job_id: `scraped-${Buffer.from((raw.url || raw.link || raw.title || '') + Math.random()).toString('base64').slice(0,20)}`,
      source: 'Scraped',
      job_title: raw.title || raw.name || raw.position || '',
      company: raw.company || raw.company_name || raw.employer || '',
      job_url: raw.url || raw.link || raw.apply_url || '',
      location_text: raw.location || raw.remote_location || '',
      salary: raw.salary || raw.compensation || '',
      description: raw.description || raw.snippet || raw.body || '',
      posted_date: raw.created_at || raw.date || '',
      tags: raw.tags || raw.skills || '',
      date_found: now
    });
  }
}

// Apply keyword filter — only pass jobs matching search intent
const KEYWORDS = [
  'async remote','asynchronous remote','worldwide remote','global remote',
  'work from anywhere','remote data analyst','remote data scientist',
  'remote ai marketing','remote marketing analyst','remote growth analyst',
  'remote bi analyst','remote automation','remote ai workflow',
  'data analyst','data scientist','business intelligence','bi analyst',
  'marketing analyst','performance marketing','growth analyst',
  'ai marketing','ai automation','ai workflow','martech'
];

const filtered = allJobs.filter(job => {
  const haystack = `${job.job_title} ${job.description} ${job.tags}`.toLowerCase();
  return KEYWORDS.some(kw => haystack.includes(kw));
});

return filtered.map(j => ({ json: j }));

// Deduplicate: skip jobs already in Google Sheets
const existingRows = $('Read Existing Jobs').all();
const existingUrls = new Set(existingRows.map(r => r.json.job_url).filter(Boolean));
const existingKeys = new Set(
  existingRows.map(r => `${r.json.company}||${r.json.job_title}`).filter(Boolean)
);

const newJobs = [];
for (const item of $('Normalize & Keyword Filter').all()) {
  const job = item.json;
  if (existingUrls.has(job.job_url)) continue;
  const key = `${job.company}||${job.job_title}`;
  if (existingKeys.has(key)) continue;
  newJobs.push({ json: job });
}

return newJobs;

// Taiwan eligibility hard filter — rule-based, no AI cost
const REJECT_PATTERNS = [
  /\bus only\b/i, /\busa only\b/i, /\bunited states only\b/i,
  /\bcanada only\b/i, /\buk only\b/i, /\bunited kingdom only\b/i,
  /\beu only\b/i, /\beurope only\b/i, /\beuropean union only\b/i,
  /\baustralia only\b/i, /\baust only\b/i,
  /\bmust be based in\b/i, /\bmust live in\b/i,
  /\bmust be authorized to work in\b/i,
  /\blocal work permit required\b/i,
  /\bhybrid\b/i, /\bonsite\b/i, /\bon-site\b/i, /\bon site\b/i,
  /\boffice required\b/i, /\bin-office\b/i,
  /\bremote within [a-z ]+only\b/i,
  /\bfixed us hours\b/i, /\bfixed eu hours\b/i,
  /\best hours required\b/i, /\bpst hours required\b/i,
  /\bcet hours required\b/i, /\bgmt hours required\b/i,
  /\bmust work 9.?5 est\b/i, /\bmust overlap.{0,20}us\b/i
];

const KEEP_PATTERNS = [
  /\bworldwide remote\b/i, /\bglobal remote\b/i,
  /\bwork from anywhere\b/i, /\banywhere in the world\b/i,
  /\bapac remote\b/i, /\binternational contractors\b/i,
  /\bcontractor role\b/i, /\bb2b contractor\b/i,
  /\bdeel\b/i, /\bremote\.com\b/i, /\boyster\b/i,
  /\beor\b/i, /\bemployer of record\b/i,
  /\bremote[- ]first\b/i, /\bdistributed team\b/i,
  /\bfully remote\b/i, /\b100% remote\b/i
];

const passed = [];
const rejected = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.location_text} ${job.description} ${job.tags}`.toLowerCase();

  const rejectMatch = REJECT_PATTERNS.find(p => p.test(text));
  if (rejectMatch) {
    job._hard_reject_reason = rejectMatch.toString();
    rejected.push({ json: job });
    continue;
  }

  const keepMatch = KEEP_PATTERNS.find(p => p.test(text));
  job._hard_filter_pass = keepMatch ? keepMatch.toString() : 'no_restriction_found';
  passed.push({ json: job });
}

// Store rejected for later sheet write — attach to global context via env isn't ideal,
// so we tag and pass all, letting downstream route them
const all = [
  ...passed.map(j => ({ json: { ...j.json, _filter_stage: 'passed' } })),
  ...rejected.map(j => ({ json: { ...j.json, _filter_stage: 'hard_rejected' } }))
];

return all;

// Parse AI response and attach to job data
// Input comes from the AI node — need to pair with original job data
const aiOutput = $input.first().json;

// Extract text from Claude response
const content = aiOutput?.content?.[0]?.text || '{}';
let aiResult;
try {
  // Claude sometimes wraps JSON in backticks
  const clean = content.replace(/```json?\n?/g, '').replace(/```/g, '').trim();
  aiResult = JSON.parse(clean);
} catch (e) {
  aiResult = {
    taiwan_eligible: 'unclear',
    reason: 'AI parse error',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };
}

// The batch node passes through the original item context
// We retrieve original job via the batch context
const jobs = $('Batch for AI').all();
const results = [];

for (const job of jobs) {
  results.push({
    json: {
      ...job.json,
      taiwan_eligible: aiResult.taiwan_eligible,
      taiwan_reason: aiResult.reason,
      location_risk: aiResult.location_risk,
      timezone_risk: aiResult.timezone_risk,
      contractor_possible: aiResult.contractor_possible,
      ai_decision: aiResult.decision
    }
  });
}

return results;

// Async filter — score async level and filter strictly async/flexible jobs
const ASYNC_HIGH = [
  /\basync\b/i, /\basynchronous\b/i,
  /\bflexible hours\b/i, /\bflexible schedule\b/i,
  /\bno meetings\b/i, /\blow meeting\b/i,
  /\bwork across time zones\b/i, /\bwork across timezones\b/i
];
const ASYNC_MED = [
  /\bdistributed team\b/i, /\bremote[- ]first\b/i,
  /\bfully distributed\b/i, /\bwork your own hours\b/i
];
const ASYNC_LOW = [
  /\b100% remote\b/i, /\bfully remote\b/i
];
const ASYNC_REJECT = [
  /\bstrict 9.?5\b/i, /\bfixed us hours\b/i,
  /\bfixed est hours\b/i, /\bfixed pst hours\b/i,
  /\bfixed cet hours\b/i, /\bdaily live calls required\b/i,
  /\bmust overlap full business day\b/i,
  /\breal.?time availability required\b/i
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.description} ${job.tags} ${job.job_title}`.toLowerCase();

  if (ASYNC_REJECT.some(p => p.test(text))) {
    continue; // drop
  }

  let async_level = 'unknown';
  if (ASYNC_HIGH.some(p => p.test(text))) async_level = 'high';
  else if (ASYNC_MED.some(p => p.test(text))) async_level = 'medium';
  else if (ASYNC_LOW.some(p => p.test(text))) async_level = 'low';

  results.push({ json: { ...job, async_level } });
}

return results;

// Role fit filter and categorization
const ROLE_CATEGORIES = [
  {
    category: 'Data Analyst',
    patterns: [/\bdata analyst\b/i, /\bdata analysis\b/i, /\banalyst\b/i]
  },
  {
    category: 'Data Scientist',
    patterns: [/\bdata scientist\b/i, /\bjunior data scientist\b/i, /\bml engineer\b/i]
  },
  {
    category: 'BI Analyst',
    patterns: [/\bbi analyst\b/i, /\bbusiness intelligence\b/i, /\btableau\b/i, /\bpower bi\b/i]
  },
  {
    category: 'Marketing Analyst',
    patterns: [/\bmarketing analyst\b/i, /\bperformance marketing\b/i, /\bgrowth analyst\b/i, /\bseo analyst\b/i, /\bppc analyst\b/i]
  },
  {
    category: 'AI Marketing',
    patterns: [/\bai marketing\b/i, /\bai[- ]assisted\b/i, /\bmartech\b/i, /\bcreative strategist\b/i]
  },
  {
    category: 'AI Automation',
    patterns: [/\bai automation\b/i, /\bai workflow\b/i, /\bautomation specialist\b/i, /\bn8n\b/i, /\bmake\.com\b/i, /\bzapier\b/i]
  },
  {
    category: 'Growth Analyst',
    patterns: [/\bgrowth analyst\b/i, /\bgrowth hacker\b/i, /\bgrowth marketing\b/i]
  }
];

const PRIMARY_ROLES = ROLE_CATEGORIES.map(r => r.patterns).flat();
const ADJACENT_PATTERNS = [
  /\bproduct analyst\b/i, /\bcontent strategist\b/i,
  /\bdigital marketing\b/i, /\banalytics\b/i, /\breporting\b/i,
  /\bdashboard\b/i, /\bsql\b/i, /\bpython\b/i
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.job_title} ${job.description} ${job.tags}`;

  let role_category = 'other';
  let role_fit = 'low';

  for (const rc of ROLE_CATEGORIES) {
    if (rc.patterns.some(p => p.test(text))) {
      role_category = rc.category;
      role_fit = 'primary';
      break;
    }
  }

  if (role_fit === 'low' && ADJACENT_PATTERNS.some(p => p.test(text))) {
    role_fit = 'adjacent';
    role_category = 'Adjacent Role';
  }

  results.push({ json: { ...job, role_category, role_fit } });
}

return results;

// Scoring system — 0 to 100
// Taiwan eligibility: 40/30/20/0
// Async fit: 25/20/15/10
// Role fit: 25/15
// Salary fit: 10/15/25

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  let score = 0;
  const scoreBreakdown = [];

  // Taiwan eligibility (40 pts max)
  const descLower = `${job.location_text} ${job.description} ${job.tags}`.toLowerCase();
  if (
    job.taiwan_eligible === 'yes' ||
    /worldwide|work from anywhere|global remote|contractor|international/i.test(descLower)
  ) {
    score += 40;
    scoreBreakdown.push('Taiwan: +40 (clearly eligible)');
  } else if (/apac|asia.pacific/i.test(descLower)) {
    score += 30;
    scoreBreakdown.push('Taiwan: +30 (APAC friendly)');
  } else if (job.taiwan_eligible === 'unclear' && job.location_risk !== 'high') {
    score += 20;
    scoreBreakdown.push('Taiwan: +20 (no clear restriction)');
  } else {
    scoreBreakdown.push('Taiwan: +0 (restricted)');
  }

  // Async fit (25 pts max)
  if (job.async_level === 'high') {
    score += 25;
    scoreBreakdown.push('Async: +25 (clearly async)');
  } else if (job.async_level === 'medium') {
    score += 20;
    scoreBreakdown.push('Async: +20 (flexible hours)');
  } else if (job.async_level === 'low') {
    score += 15;
    scoreBreakdown.push('Async: +15 (distributed team)');
  } else {
    score += 10;
    scoreBreakdown.push('Async: +10 (remote first)');
  }

  // Role fit (25 pts max)
  if (job.role_fit === 'primary') {
    score += 25;
    scoreBreakdown.push(`Role: +25 (${job.role_category})`);
  } else if (job.role_fit === 'adjacent') {
    score += 15;
    scoreBreakdown.push('Role: +15 (adjacent role)');
  } else {
    scoreBreakdown.push('Role: +0 (not matched)');
  }

  // Salary fit (25 pts max)
  const salaryText = (job.salary || '').replace(/[^0-9,kK]/g, '');
  const salaryNum = parseFloat(salaryText.replace(/[,kK]/g, '')) *
    (salaryText.toLowerCase().includes('k') ? 1000 : 1);
  if (salaryNum >= 5000) {
    score += 25;
    scoreBreakdown.push('Salary: +25 (≥$5k/mo)');
  } else if (salaryNum >= 3000) {
    score += 15;
    scoreBreakdown.push('Salary: +15 (≥$3k/mo)');
  } else if (job.salary && job.salary.length > 0) {
    score += 10;
    scoreBreakdown.push('Salary: +10 (listed)');
  } else {
    scoreBreakdown.push('Salary: +0 (not listed)');
  }

  // Why good fit summary
  const whyGoodFit = [
    job.taiwan_eligible === 'yes' ? 'Taiwan eligible' : '',
    job.async_level === 'high' ? 'Async-first' : job.async_level === 'medium' ? 'Flexible hours' : '',
    job.role_category !== 'other' ? `Matches ${job.role_category}` : '',
    job.salary ? `Salary: ${job.salary}` : ''
  ].filter(Boolean).join(' | ');

  results.push({
    json: {
      ...job,
      score,
      score_breakdown: scoreBreakdown.join(' | '),
      why_good_fit: whyGoodFit
    }
  });
}

// Sort by score descending
results.sort((a, b) => b.json.score - a.json.score);

return results;

// Attach cover letter to job data
const job = $('Score ≥ 85?').first().json;
const aiResp = $input.first().json;
const coverLetter = aiResp?.content?.[0]?.text || 'Cover letter generation failed.';

return [{ json: { ...job, cover_letter: coverLetter } }];

// Compile daily digest from all filtered jobs
const allFiltered = $('Write Filtered Jobs to Sheet').all();

const topJobs = allFiltered
  .map(i => i.json)
  .sort((a, b) => b.score - a.score)
  .slice(0, 10);

const manualCheck = allFiltered
  .map(i => i.json)
  .filter(j => j.taiwan_eligible === 'unclear' && j.score >= 70);

// Count rejections from hard filter stage (passed through with _filter_stage)
const allRaw = $('Taiwan Hard Filter').all().map(i => i.json);
const rejectedUS = allRaw.filter(j => j._hard_reject_reason && /us only|usa only|united states/i.test(j._hard_reject_reason)).length;
const rejectedEU = allRaw.filter(j => j._hard_reject_reason && /eu only|europe/i.test(j._hard_reject_reason)).length;
const rejectedHybrid = allRaw.filter(j => j._hard_reject_reason && /hybrid|onsite/i.test(j._hard_reject_reason)).length;
const rejectedTZ = allRaw.filter(j => j._hard_reject_reason && /fixed .+ hours/i.test(j._hard_reject_reason)).length;

const jobLines = topJobs.map((job, i) => `
${i + 1}. ${job.job_title}
   Company: ${job.company}
   Score: ${job.score}/100
   Taiwan eligible: ${job.taiwan_eligible}
   Reason: ${job.taiwan_reason || 'N/A'}
   Async level: ${job.async_level}
   Timezone risk: ${job.timezone_risk}
   Salary: ${job.salary || 'Not listed'}
   Why it fits Jerry: ${job.why_good_fit}
   Apply: ${job.job_url}
`).join('');

const manualLines = manualCheck.length
  ? manualCheck.map(j => `• ${j.job_title} @ ${j.company} (Score: ${j.score}) — ${j.taiwan_reason}`).join('\n')
  : 'None today.';

const digest = `
📋 Daily Taiwan Eligible Async Remote Jobs — ${new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' })}

🏆 Top Jobs Today (${topJobs.length} of ${allFiltered.length} passed filters):
${jobLines}

⚠️ Manual Check (unclear eligibility, high score):
${manualLines}

❌ Rejected Summary:
• US only: ${rejectedUS}
• EU only: ${rejectedEU}
• Hybrid/onsite: ${rejectedHybrid}
• Timezone risk: ${rejectedTZ}
• Total rejected: ${allRaw.filter(j => j._filter_stage === 'hard_rejected').length}

✅ Passed filters: ${allFiltered.length}
`;

return [{ json: { digest, topJobsCount: topJobs.length, filteredCount: allFiltered.length } }];

